// Normalize input from both triggers
const webhookBody = $input.item.json.body || $input.item.json;

// Webhook trigger — direct request
if (webhookBody.nodeName) {
  return [{
    json: {
      nodeName: webhookBody.nodeName,
      displayName: webhookBody.displayName || webhookBody.nodeName,
      description: webhookBody.description || '',
      category: webhookBody.category || 'aisha',
      requestId: webhookBody.requestId || null,
      trigger: 'webhook'
    }
  }];
}

// Cron trigger — pass through to downstream aishaRpc node
// (pending requests fetched by upstream aishaRpc node if wired)
return [{ json: { skip: true, trigger: 'cron', message: 'No webhook payload — cron trigger should be wired to fetch pending requests via aishaRpc node' } }];

// STAGE 1: Generate node code using AishaNodeFactory logic
const request = $input.item.json;

const className = request.nodeName.replace(/[^a-zA-Z0-9]/g, '');
const nodeId = className.charAt(0).toLowerCase() + className.slice(1);

// Generate the node TypeScript code
const operations = request.operations.map(op => `'${op}'`).join(' | ');
const opsArray = request.operations.map(op => {
  return `{ name: '${op.charAt(0).toUpperCase() + op.slice(1)}', value: '${op}' }`;
}).join(',\n\t\t\t\t\t');

const rpcCases = request.rpcFunctions.map(fn => {
  return `\t\t\t\tcase '${fn}':\n\t\t\t\t\trpcFunction = '${fn}';\n\t\t\t\t\trpcParams = {};\n\t\t\t\t\tbreak;`;
}).join('\n');

const auditBlock = request.includeAudit ? `
\t\t\t// Audit trail
\t\t\ttry {
\t\t\t\tawait fetch(supabaseUrl + '/rest/v1/rpc/insert_audit_journal_entry', {
\t\t\t\t\tmethod: 'POST',
\t\t\t\t\theaders: {
\t\t\t\t\t\t'Content-Type': 'application/json',
\t\t\t\t\t\t'apikey': credentials.serviceRoleKey,
\t\t\t\t\t\t'Authorization': \`Bearer \${credentials.serviceRoleKey}\`,
\t\t\t\t\t},
\t\t\t\t\tbody: JSON.stringify({
\t\t\t\t\t\tp_action: 'CUSTOM_NODE_EXECUTE',
\t\t\t\t\t\tp_metadata: { node: '${className}', operation },
\t\t\t\t\t}),
\t\t\t\t});
\t\t\t} catch { /* audit is best-effort */ }` : '';

const code = `import { IExecuteFunctions, INodeExecutionData, INodeType, INodeTypeDescription } from 'n8n-workflow';

export class ${className} implements INodeType {
\tdescription: INodeTypeDescription = {
\t\tdisplayName: 'AISHA ${request.description.substring(0, 40)}',
\t\tname: 'aisha${className}',
\t\ticon: 'file:aisha.svg',
\t\tgroup: ['transform'],
\t\tversion: 1,
\t\tsubtitle: '={{$parameter["operation"]}}',
\t\tdescription: '${request.description.replace(/'/g, "\\'").substring(0, 120)}',
\t\tdefaults: { name: '${className}' },
\t\tinputs: ['main'],
\t\toutputs: ['main'],
\t\tcredentials: [{ name: 'aishaPostgrestApi', required: true }],
\t\tproperties: [
\t\t\t{
\t\t\t\tdisplayName: 'Operation',
\t\t\t\tname: 'operation',
\t\t\t\ttype: 'options',
\t\t\t\tnoDataExpression: true,
\t\t\t\toptions: [${opsArray}],
\t\t\t\tdefault: '${request.operations[0]}',
\t\t\t},
\t\t],
\t};

\tasync execute(this: IExecuteFunctions): Promise<INodeExecutionData[][]> {
\t\tconst items = this.getInputData();
\t\tconst results: INodeExecutionData[] = [];
\t\tconst credentials = await this.getCredentials('aishaPostgrestApi');
\t\tconst supabaseUrl = credentials.supabaseUrl as string;

\t\tfor (let i = 0; i < items.length; i++) {
\t\t\ttry {
\t\t\t\tconst operation = this.getNodeParameter('operation', i) as string;
\t\t\t\tlet rpcFunction = '';
\t\t\t\tlet rpcParams: Record<string, unknown> = {};

\t\t\t\tswitch (operation) {
${rpcCases || '\t\t\t\tdefault:\n\t\t\t\t\tthrow new Error(\`Unknown operation: \${operation}\`);'}
\t\t\t\t}

\t\t\t\tconst resp = await fetch(supabaseUrl + '/rest/v1/rpc/' + rpcFunction, {
\t\t\t\t\tmethod: 'POST',
\t\t\t\t\theaders: {
\t\t\t\t\t\t'Content-Type': 'application/json',
\t\t\t\t\t\t'apikey': credentials.serviceRoleKey as string,
\t\t\t\t\t\t'Authorization': \`Bearer \${credentials.serviceRoleKey}\`,
\t\t\t\t\t},
\t\t\t\t\tbody: JSON.stringify(rpcParams),
\t\t\t\t});

\t\t\t\tconst data = await resp.json();
\t\t\t\tif (!resp.ok) throw new Error(data.message || JSON.stringify(data));
\t\t\t\tresults.push({ json: typeof data === 'object' ? data : { result: data } });${auditBlock}
\t\t\t} catch (error) {
\t\t\t\tif (this.continueOnFail()) {
\t\t\t\t\tresults.push({ json: { error: (error as Error).message } });
\t\t\t\t} else {
\t\t\t\t\tthrow error;
\t\t\t\t}
\t\t\t}
\t\t}
\t\treturn [results];
\t}
}
`;

return [{
  json: {
    ...request,
    generatedCode: code,
    className,
    nodeId,
    stage: 'generated',
  }
}];

// STAGE 2: Validate generated code
const item = $input.item.json;
const code = item.generatedCode;
const issues = [];

// Structure checks
if (!code.includes('implements INodeType')) issues.push('Missing INodeType implementation');
if (!code.includes('description:')) issues.push('Missing description property');
if (!code.includes('async execute')) issues.push('Missing execute method');
if (!code.includes('continueOnFail')) issues.push('Missing continueOnFail error handling');

// Security checks
if (code.includes('eval(') || code.includes('new Function(')) issues.push('SECURITY: eval/Function detected');
if (code.includes('.select("*")') || code.includes(".select('*')")) issues.push('SECURITY: select("*") detected');
if (code.includes('console.log')) issues.push('HYGIENE: console.log found (use audit instead)');

// Naming convention
if (!item.className.startsWith('Aisha')) issues.push('NAMING: Class name must start with Aisha');

const isValid = issues.length === 0;

return [{
  json: {
    ...item,
    validation: {
      isValid,
      issues,
      checkedAt: new Date().toISOString(),
    },
    stage: isValid ? 'validated' : 'validation_failed',
  }
}];

// STAGE 3: Generate test plan for the validated node
const item = $input.item.json;
const className = item.className;
const operations = item.operations;

const testCases = [
  `describe('${className}', () => {`,
  `  it('should have correct node description', () => {`,
  `    const node = new ${className}();`,
  `    expect(node.description.name).toBe('aisha${className}');`,
  `    expect(node.description.version).toBe(1);`,
  `  });`,
  '',
  ...operations.map(op => [
    `  it('should execute ${op} operation', async () => {`,
    `    const ctx = createMockExecuteFunctions({ operation: '${op}' });`,
    `    setupFetchMock({ success: true });`,
    `    const node = new ${className}();`,
    `    const result = await node.execute.call(ctx);`,
    `    expect(result[0]).toBeDefined();`,
    `  });`,
    '',
  ].join('\n')).flat(),
  `  it('should handle errors with continueOnFail', async () => {`,
  `    const ctx = createMockExecuteFunctions({ operation: '${operations[0]}', continueOnFail: true });`,
  `    setupFetchMock({ message: 'Test error' }, false);`,
  `    const node = new ${className}();`,
  `    const result = await node.execute.call(ctx);`,
  `    expect(result[0][0].json.error).toBeDefined();`,
  `  });`,
  `});`,
];

const testCode = [
  `import { describe, it, expect, beforeEach } from 'vitest';`,
  `import { ${className} } from '../nodes/${className}/${className}.node';`,
  `import { createMockExecuteFunctions, setupFetchMock } from './helpers/mockFactory';`,
  '',
  ...testCases,
].join('\n');

return [{
  json: {
    ...item,
    generatedTestCode: testCode,
    testCount: operations.length + 2,
    stage: 'tested',
  }
}];

// Final output — summarize what happened
const item = $input.item.json;

return [{
  json: {
    status: item.stage === 'registered' ? 'SUCCESS' : 'COMPLETED_WITH_ISSUES',
    nodeName: item.className,
    nodeType: `n8n-nodes-aisha.aisha${item.className}`,
    operations: item.operations,
    category: item.category,
    generatedAt: new Date().toISOString(),
    validation: item.validation,
    registration: item.registration,
    testCount: item.testCount,
    codeLength: item.generatedCode?.length || 0,
    nextSteps: [
      'Review generated code in PR',
      'Run tests: cd packages/n8n-nodes-aisha && npm test',
      'Deploy: npm run deploy:n8n --coolify',
    ],
  }
}];

// Validation failed — log issues and notify
const item = $input.item.json;

return [{
  json: {
    status: 'VALIDATION_FAILED',
    nodeName: item.className,
    issues: item.validation.issues,
    suggestion: 'Fix issues and re-submit via webhook or wait for next cron cycle.',
    stage: 'validation_failed',
    requestId: item.requestId,
    source: item.source,
  }
}];
